export interface ConnectorConfig {
  /** Trello API Key from https://trello.com/app-key */
  trelloApiKey: string
  /** Trello API Token from https://trello.com/app-key (generated per user) */
  trelloApiToken: string
  /** Trello Card ID where the checklist will be added */
  cardId: string
  /** Optional checklist name to create/find on the card */
  checklistName?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface GoogleCalendarWebhookPayload {
  triggerEvent: string
  createdAt: string
  payload: {
    triggerEvent: string
    id: number
    uid: string
    title: string
    description: string
    startTime: string
    endTime: string
    location: string
    status: string
    paid: boolean
    createdAt: string
    updatedAt: string
    userId: number
    eventTypeId: number
    metadata: Record<string, unknown>
    responses: {
      name: { label: string; value: string }
      email: { label: string; value: string }
    }
    user: {
      email: string
      name: string
      username: string
      timeZone: string
      locale: string
    }
    attendees: Array<{
      id: number
      name: string
      email: string
      timeZone: string
      locale: string
      noShow: boolean
    }>
    payment: unknown[]
    references: Array<{
      id: number
      type: string
      uid: string
      meetingId: string
      meetingUrl: string
    }>
  }
}

export interface HandleResult {
  checklistId: string
  checkItemId: string
  attendeeEmail: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function buildUrlWithAuth(baseUrl: string, apiKey: string, apiToken: string): string {
  const url = new URL(baseUrl)
  url.searchParams.set('key', apiKey)
  url.searchParams.set('token', apiToken)
  return url.toString()
}

async function createChecklist(
  fetchFn: typeof fetch,
  cardId: string,
  checklistName: string,
  apiKey: string,
  apiToken: string,
): Promise<string> {
  const url = buildUrlWithAuth('https://api.trello.com/1/checklists', apiKey, apiToken)
  const body = JSON.stringify({ name: checklistName, idCard: cardId })
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body,
  })
  if (!response.ok) {
    throw new Error(`Trello create checklist failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string }
  return data.id
}

async function addChecklistItem(
  fetchFn: typeof fetch,
  checklistId: string,
  itemName: string,
  apiKey: string,
  apiToken: string,
): Promise<string> {
  const url = buildUrlWithAuth(`https://api.trello.com/1/checklists/${checklistId}/checkItems`, apiKey, apiToken)
  const body = JSON.stringify({ name: itemName })
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body,
  })
  if (!response.ok) {
    throw new Error(`Trello add checklist item failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string }
  return data.id
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = getFetch(config)

  // Validate required fields
  if (!payload.payload?.attendees?.length) {
    throw new Error('Missing required field: payload.attendees array is empty or missing')
  }
  const firstAttendee = payload.payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('Missing required field: payload.attendees[0].email')
  }
  if (!config.cardId) {
    throw new Error('Missing required config: cardId')
  }
  if (!config.trelloApiKey) {
    throw new Error('Missing required config: trelloApiKey')
  }
  if (!config.trelloApiToken) {
    throw new Error('Missing required config: trelloApiToken')
  }

  const attendeeEmail = firstAttendee.email
  const checklistName = config.checklistName ?? 'Attendee Checklist'

  // Create checklist on the card
  const checklistId = await createChecklist(
    fetchFn,
    config.cardId,
    checklistName,
    config.trelloApiKey,
    config.trelloApiToken,
  )

  // Add checklist item with attendee email
  const checkItemId = await addChecklistItem(
    fetchFn,
    checklistId,
    attendeeEmail,
    config.trelloApiKey,
    config.trelloApiToken,
  )

  return {
    checklistId,
    checkItemId,
    attendeeEmail,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, GoogleCalendarWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      cardId: 'abc123',
      checklistName: 'Attendee Checklist',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.attendeeEmail).toBe('john.doe@example.com')
    expect(result.checklistId).toBe('checklist_123')
    expect(result.checkItemId).toBe('checkitem_456')
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const { fetch: f, calls: c } = fakeFetch((req) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      if (req.url.includes('/checkItems')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = f
    calls = c
    baseConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      cardId: 'card-123',
      checklistName: 'Attendee Checklist',
      fetch,
    }
  })

  it('happy path: creates checklist and adds item with attendee email', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    const result = await handle(payload, baseConfig)

    expect(result.attendeeEmail).toBe('john.doe@example.com')
    expect(result.checklistId).toBe('checklist_123')
    expect(result.checkItemId).toBe('checkitem_456')
    expect(calls.length).toBe(2)

    // First call: create checklist
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toContain('/checklists')
    expect(calls[0].url).toContain('key=test-key')
    expect(calls[0].url).toContain('token=test-token')
    expect(calls[0].json).toEqual({ name: 'Attendee Checklist', idCard: 'card-123' })

    // Second call: add checklist item
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toContain('/checklists/checklist_123/checkItems')
    expect(calls[1].url).toContain('key=test-key')
    expect(calls[1].url).toContain('token=test-token')
    expect(calls[1].json).toEqual({ name: 'john.doe@example.com' })
  })

  it('uses auth query parameters key and token', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    await handle(payload, baseConfig)

    for (const call of calls) {
      expect(call.url).toContain('key=test-key')
      expect(call.url).toContain('token=test-token')
    }
  })

  it('maps attendees[0].email to checklist item name', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    await handle(payload, baseConfig)

    const itemCall = calls.find((c) => c.url.includes('/checkItems'))
    expect(itemCall).toBeDefined()
    expect(itemCall!.json).toEqual({ name: 'john.doe@example.com' })
  })

  it('maps config.cardId to checklist idCard', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    await handle(payload, baseConfig)

    const checklistCall = calls.find((c) => c.url.endsWith('/checklists') || c.url.endsWith('/checklists?key=test-key&token=test-token'))
    expect(checklistCall).toBeDefined()
    expect(checklistCall!.json).toEqual({ name: 'Attendee Checklist', idCard: 'card-123' })
  })

  it('throws when attendees array is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, attendees: undefined },
    } as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: payload.attendees array is empty or missing')
  })

  it('throws when attendees array is empty', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, attendees: [] },
    } as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: payload.attendees array is empty or missing')
  })

  it('throws when first attendee email is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, attendees: [{ ...SOURCE_EXAMPLE.payload.attendees[0], email: '' }] },
    } as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: payload.attendees[0].email')
  })

  it('throws when config.cardId is missing', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    const config = { ...baseConfig, cardId: '' }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: cardId')
  })

  it('throws when config.trelloApiKey is missing', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    const config = { ...baseConfig, trelloApiKey: '' }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: trelloApiKey')
  })

  it('throws when config.trelloApiToken is missing', async () => {
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    const config = { ...baseConfig, trelloApiToken: '' }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: trelloApiToken')
  })

  it('throws on non-2xx response from create checklist', async () => {
    const { fetch: errorFetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config = { ...baseConfig, fetch: errorFetch }
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Trello create checklist failed: 401 Unauthorized at')
    expect(errorCalls.length).toBe(1)
  })

  it('throws on non-2xx response from add checklist item', async () => {
    const { fetch: errorFetch, calls: errorCalls } = fakeFetch((req) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      return jsonResponse({ error: 'Not Found' }, 404)
    })
    const config = { ...baseConfig, fetch: errorFetch }
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Trello add checklist item failed: 404 Not Found at')
    expect(errorCalls.length).toBe(2)
  })

  it('uses default checklist name when not configured', async () => {
    const config = { ...baseConfig, checklistName: undefined }
    const payload = SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload
    await handle(payload, config)

    const checklistCall = calls.find((c) => c.url.includes('/checklists') && !c.url.includes('/checkItems'))
    expect(checklistCall).toBeDefined()
    expect(checklistCall!.json).toEqual({ name: 'Attendee Checklist', idCard: 'card-123' })
  })
})

