export interface HandleResult {
  checklistId: string
  checkItemId: string
  attendeeEmail: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function buildUrlWithAuth(baseUrl: string, apiKey: string, apiToken: string): string {
  const url = new URL(baseUrl)
  url.searchParams.set('key', apiKey)
  url.searchParams.set('token', apiToken)
  return url.toString()
}

async function createChecklist(
  fetchFn: typeof fetch,
  cardId: string,
  checklistName: string,
  apiKey: string,
  apiToken: string,
): Promise<string> {
  const url = buildUrlWithAuth('https://api.trello.com/1/checklists', apiKey, apiToken)
  const body = JSON.stringify({ name: checklistName, idCard: cardId })
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body,
  })
  if (!response.ok) {
    throw new Error(`Trello create checklist failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string }
  return data.id
}

async function addChecklistItem(
  fetchFn: typeof fetch,
  checklistId: string,
  itemName: string,
  apiKey: string,
  apiToken: string,
): Promise<string> {
  const url = buildUrlWithAuth(`https://api.trello.com/1/checklists/${checklistId}/checkItems`, apiKey, apiToken)
  const body = JSON.stringify({ name: itemName })
  const response = await fetchFn(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body,
  })
  if (!response.ok) {
    throw new Error(`Trello add checklist item failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string }
  return data.id
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = getFetch(config)

  // Validate required fields
  if (!payload.payload?.attendees?.length) {
    throw new Error('Missing required field: payload.attendees array is empty or missing')
  }
  const firstAttendee = payload.payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('Missing required field: payload.attendees[0].email')
  }
  if (!config.cardId) {
    throw new Error('Missing required config: cardId')
  }
  if (!config.trelloApiKey) {
    throw new Error('Missing required config: trelloApiKey')
  }
  if (!config.trelloApiToken) {
    throw new Error('Missing required config: trelloApiToken')
  }

  const attendeeEmail = firstAttendee.email
  const checklistName = config.checklistName ?? 'Attendee Checklist'

  // Create checklist on the card
  const checklistId = await createChecklist(
    fetchFn,
    config.cardId,
    checklistName,
    config.trelloApiKey,
    config.trelloApiToken,
  )

  // Add checklist item with attendee email
  const checkItemId = await addChecklistItem(
    fetchFn,
    checklistId,
    attendeeEmail,
    config.trelloApiKey,
    config.trelloApiToken,
  )

  return {
    checklistId,
    checkItemId,
    attendeeEmail,
  }
}

